prefix_claim_recomputation_shell_command:
.venv/bin/python -c 'import json,collections; from pathlib import Path; from experiments.openexempt_online import native_claim_feedback; from legal_skill_guard.openexempt import metrics
src=Path("runs/legal_openexempt_revision_outcomes_shared_controls_public_assets128_20261028_run02")
pub=json.loads((src/"publications/b4.json").read_text())
old={(r["case_id"],r["family"]):r for r in pub["training_decisions"][-1]["actual_replay"]}
old.update({(r["case_id"],r["family"]):r for r in json.loads((src/"batches/b5_prequential_records.json").read_text())["skills"]})
assert len(old)==160 and max(k[0] for k in old)==260
groups={"parent":list(old.values())}
for arm in ("negative","paired"):
 p=Path("runs")/("legal_openexempt_paired_revision_outcome_TRAIN80_follow48_20261028_run03_"+arm)/"prefix_complete.json"
 a=json.loads(p.read_text()); d=a["publication"]["training_decisions"][0]; groups[arm+"_proposed"]=d.get("proposed_replay",d["actual_replay"])
out={}
for arm,records in groups.items():
 out[arm]={"metrics":metrics(records),"current16":metrics([r for r in records if r["case_id"]>=245]),"prior64":metrics([r for r in records if r["case_id"]<245]),"claims":{}}
 for f in ("EC","EV"):
  counts=collections.Counter(); missing=collections.Counter()
  for r in records:
   if r["family"]!=f: continue
   truth=json.loads((Path("data/packets/openexempt_closed_feedback_public_assets128_20261021/grading_only")/str(r["case_id"])).with_suffix(".json").read_text())["targets"][f]
   a=native_claim_feedback(r,truth)
   for k in ("correct","missing","incorrect_value","extra_or_duplicate","incorrect_value_predictions"): counts[k]+=a.get(k,0)
   for e in a["errors"]:
    if e["kind"]=="missing": missing[e["citation"]]+=1
  out[arm]["claims"][f]={"counts":dict(counts),"missing_by_citation":dict(missing)}
print(json.dumps(out,ensure_ascii=False,indent=2))'
